async function orders(generation=routeGeneration){if(!routeCurrent('orders',generation))return;const data=await api(`/orders?offset=${orderOffset}&q=${encodeURIComponent($('#order-search')?.value||'')}&store_id=${encodeURIComponent($('#order-store')?.value||'')}`);if(!routeCurrent('orders',generation))return;cachedOrders=data.rows;const search=$('#order-search')?.value||'',store=$('#order-store')?.value||'';$('#main').innerHTML=heading('每笔订单，都有迹可循。','统一查看各店铺订单，搜索、备注与导出。订单状态以平台同步结果为准。',`<a class="btn" href="/api/export/orders">${icon('download')} 导出</a>${btn('导入 CSV','import-orders')}${btn(icon('refresh')+' 同步订单','sync-orders',true)}`,'ORDER CENTER')+`<section class="card"><div class="toolbar"><label class="search">${icon('search')}<input id="order-search" value="${esc(search)}" placeholder="订单号、商品或备注" aria-label="搜索订单"></label><div class="actions"><select id="order-store" class="control" style="width:auto" aria-label="筛选店铺"><option value="">全部店铺</option>${state.stores.map(s=>`<option value="${s.id}" ${s.id===store?'selected':''}>${esc(s.name)}</option>`).join('')}</select>${btn('查询','search-orders')}</div></div>${data.rows.length?`<div class="table-wrap"><table><thead><tr><th>订单 / 商品</th><th>所属店铺</th><th>订单金额</th><th>平台状态</th><th>来源 / 同步</th><th>本地备注</th></tr></thead><tbody>${data.rows.map(r=>`<tr><td><strong class="mono">${esc(r.external_id)}</strong><div class="subtle wrap">${esc(r.data.items.map(i=>i.title).join(' / '))}</div></td><td>${esc(storeName(r.store_id))}</td><td class="money">${money(r.data.amount_cents)}</td><td>${badge('mapped',r.data.status)}</td><td class="subtle">${['api','browser'].includes(r.source)?'网页同步':'CSV 导入'}<br>${date(r.updated)}</td><td><button class="link-btn" data-action="order-note" data-id="${r.id}">${r.note?esc(r.note.slice(0,20)):'添加备注'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('orders','暂无订单')}<div class="table-footer"><span>共 ${data.total} 笔 · 第 ${Math.floor(orderOffset/50)+1} 页</span><div class="actions">${btn('上一页','orders-prev',false,orderOffset===0?'disabled':'')}${btn('下一页','orders-next',false,orderOffset+50>=data.total?'disabled':'')}</div></div></section><p class="inline-help">本版提供订单查询、汇总和本地备注。发货、退款、售后仍在各平台商家后台完成；网页订单按 SKU 映射自动扣减本地库存；异常请到统一库存处理。</p>`}
