async function settings(generation=routeGeneration){if(!routeCurrent('settings',generation))return;const audit=await api('/audit');if(!routeCurrent('settings',generation))return;$('#main').innerHTML=heading('让工作台，按你的方式运转。','部署信息、后台网页规则和操作记录。','','SETTINGS & CONNECTION GUIDE')+`<div class="grid-two"><section class="card"><div class="card-head"><h2>运行信息</h2>${badge('valid','服务运行中')}</div><div class="card-body"><table><tbody><tr><td>应用版本</td><td>ShopDock ${state.version}</td></tr><tr><td>电商网页引擎</td><td>${state.commerce_browser_ready?'已就绪 · 网页 Cookie 会话':'未就绪 · 需 Playwright 与 Chrome'}</td></tr><tr><td>视频发布引擎</td><td>${state.engine_ready?'MPAU 已安装':'未安装 · 需完整 Docker 镜像'}</td></tr><tr><td>扫码桌面</td><td>${state.desktop_ready?'已安装':'未安装 · 需完整 Docker 镜像'}</td></tr><tr><td>单文件上限</td><td>${state.max_upload_mb} MB</td></tr><tr><td>数据位置</td><td>Docker 持久卷 /data</td></tr></tbody></table><div class="actions mt">${btn('打开扫码窗口','desktop')}<a class="btn" href="https://github.com/cjccd/multi-platform-auto-upload" target="_blank" rel="noopener">MPAU 项目 ↗</a></div></div></section><section class="card"><div class="card-head"><h2>后台网页规则</h2><small>首次接入时配置</small></div><div class="card-body"><p class="inline-help">工作流是系统操作平台网页的步骤，包括进入商品页、填写资料、上传图片、提交和读取回执。缺少平台适配时不能直接发布，请在店铺连接中查看「店铺接入检查」。普通使用无需编写 JSON。</p><p class="inline-help">电商后台与视频账号各自保存登录状态。Cookie 失效后重新登录电商后台；视频账号的登录检查不验证电商后台。快手 Video 凭据仅用于官方视频通道。</p><details><summary>模板变量与商品字段</summary><pre>{{product.title}}\n{{product.description}}\n{{product.skus.0.price_cents}}\n{{listing.external_id}}</pre><p class="inline-help">金额使用整数「分」。后台网页字段按其显示单位转换；商品扩展资料在本地编辑后重新预检。</p></details></div></section></div><section class="card"><div class="card-head"><h2>平台能力与当前边界</h2></div>${capabilityTable()}</section><div class="notice">库存使用店铺分配额度；网页订单按 SKU 映射同步后扣账，取消与退款不自动回补实物库存。全量库存校准前须暂停销售并核对占用。正式使用前请用测试商品验证后台网页规则。备份时停止容器并备份完整数据卷，其中包含浏览器会话与 master.key。</div><section class="card"><div class="card-head"><h2>最近操作记录</h2><small>最近 100 条</small></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作</th><th>记录</th></tr></thead><tbody>${audit.slice(0,30).map(r=>`<tr><td>${date(r.created)}</td><td>${esc(r.action)}</td><td class="wrap subtle">${esc(r.detail)}</td></tr>`).join('')}</tbody></table></div></section>`}
function workbenchContext(generation=routeGeneration){return {api,state,getState:()=>state,modal,closeModal,modalCurrent:token=>token===modalGeneration&&$('#modal').open,toast,refresh,esc,heading,btn,icon,routeCurrent,generation}}
function routeName(){const name=location.hash.slice(1).split('/')[0]||'overview';return navs.some(x=>x[0]===name)?name:'overview'}
function routeCurrent(name,generation){return generation===routeGeneration&&page===name&&routeName()===name&&!$('#shell').hidden}
function stopPagePolling(){clearInterval(refreshTimer);refreshTimer=null}
function navigateTo(name){if(routeName()===name)return showPage();location.hash=name}
async function showPage(refreshData=false){
  const currentPage=routeName(),generation=++routeGeneration;
  page=currentPage;stopPagePolling();window.MediaLibrary?.leave();if(previewJob!==null)closeModal();else invalidateModalWork();renderNav();
  try{
    if(refreshData)await refresh(generation);
    if(!routeCurrent(currentPage,generation))return;
    if(currentPage==='overview')overview();
    if(currentPage==='products')products();
    if(currentPage==='stores')stores();
    if(currentPage==='library'&&window.MediaLibrary)await MediaLibrary.page(workbenchContext(generation));
    if(currentPage==='publishing'&&window.PublishWorkbench)await PublishWorkbench.page(workbenchContext(generation));
    if(currentPage==='inventory')await inventoryPage(generation);
    if(currentPage==='orders')await orders(generation);
    if(currentPage==='videos')videos();
    if(currentPage==='tasks'){
      await tasks(generation);
      if(!routeCurrent('tasks',generation))return;
      let polling=false;
      const timer=setInterval(async()=>{
        if(!routeCurrent('tasks',generation)){clearInterval(timer);if(refreshTimer===timer)refreshTimer=null;return}
        if(polling||$('#modal').open)return;
        polling=true;
        try{await tasks(generation)}catch{}finally{polling=false}
      },5000);
      refreshTimer=timer;
    }
    if(currentPage==='settings')await settings(generation);
  }catch(e){if(routeCurrent(currentPage,generation))$('#main').innerHTML=`<div class="error-state">${esc(e.message)} ${btn('重试','refresh-page')}</div>`}
}
function batchModal(kind='product_create'){if((kind.startsWith('product')||kind==='inventory_sync')&&!selected.size){toast('请先勾选至少一件商品',true);return}const sync=kind==='order_sync',stock=kind==='inventory_sync';modal(sync?'同步多平台订单':'批量操作平台商品',`<form id="batch-form">${sync?'<p class="inline-help">按订单更新时间查询，覆盖选择的时间范围。重复订单自动合并，不会重复累计。</p>':`<div class="notice info">已选 ${selected.size} 件商品；请核对目标店铺与操作。</div>`}${stock?'<input type="hidden" name="kind" value="inventory_sync"><label class="check-label"><input type="checkbox" name="sales_paused" required>我已暂停目标商品销售，并核对待付款 / 锁定库存，可进行全量可售库存校准。</label>':!sync?selectField('操作类型','kind',[['product_create','创建新商品'],['product_update','更新已有商品'],['product_list','上架已有商品'],['product_delist','下架已有商品']],kind):'<input type="hidden" name="kind" value="order_sync">'}${checks('commerce')}${sync?`<div class="form-grid mt">${field('开始时间','since',localDateValue(new Date(Date.now()-86400000)),'datetime-local')}${field('结束时间','until',localDateValue(new Date()),'datetime-local')}</div><p class="inline-help">一次最多 7 天。六个平台均使用各自的电商后台网页登录会话；需配置订单页读取规则。也可用 CSV 汇总。</p>`:field('预约执行（可选）','scheduled','','datetime-local')}${formFooter('预检并查看请求')}</form>`)}
function localDateValue(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
async function preflight(body){const r=await api('/jobs/preflight',{method:'POST',body});pendingBatch=body;modal('提交前，核对一次',`<div class="notice ${r.ready?'info':''}">${r.items.length} 项任务 · ${r.ready} 项就绪 · ${r.items.length-r.ready} 项需要配置。就绪任务将发往对应平台；未就绪任务保留为“待配置”。</div>${r.items.map(i=>`<div class="channel-row">${logo(i.platform)}<div style="flex:1"><strong>${esc(i.store_name)} · ${kindName(i.kind)}</strong><small>${esc(problemSummary(i.problem)||'本地预检通过；平台仍会校验权限与类目资料')}</small>${missingCommerceAdapter(i.problem)?`<details><summary>技术详情</summary><pre>${esc(i.problem)}</pre></details>${btn('查看接入检查','commerce-readiness',false,`data-id="${i.store_id}"`)}`:''}</div>${badge(i.problem?'blocked':'valid',i.problem?'待配置':'就绪')}</div>${i.platform==='kuaishou'&&i.kind==='product_create'?kuaishouPreviewButton(i.entity_id||i.payload.product?.id,i.store_id):''}${i.payload.request?`<details><summary>查看提交参数</summary><pre>${esc(JSON.stringify(i.payload.request,null,2))}</pre></details>`:''}`).join('')}<div class="form-footer">${btn('返回修改','close')}${btn(r.ready?'确认加入任务队列':'保存为待配置任务','commit-batch',true)}</div>`)}
function uploadModal(){modal('上传素材',`<form id="upload-form"><div class="upload-zone">${icon('upload')}<p>选择视频或商品图片</p><small>MP4 / MOV / WebM / JPG / PNG / WebP · 最多 ${state.max_upload_mb} MB</small><input type="file" name="file" accept=".mp4,.mov,.webm,.jpg,.jpeg,.png,.webp" required></div><p class="inline-help">文件保存在本地。上传素材不会自动发布到任何平台。</p><div id="upload-progress" class="subtle"></div>${formFooter('上传到素材库')}</form>`)}
async function uploadFile(file,progress){const fd=new FormData();fd.append('file',file);return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/media');xhr.setRequestHeader('X-CSRF-Token',csrf);xhr.upload.onprogress=e=>{if(progress&&e.lengthComputable)progress.textContent=`正在上传 ${Math.round(e.loaded/e.total*100)}%`};xhr.onerror=()=>reject(Error('上传连接中断'));xhr.onload=()=>{let r;try{r=JSON.parse(xhr.responseText)}catch{reject(Error('上传失败，请查看服务日志'));return}if(xhr.status>=200&&xhr.status<300)resolve(r);else reject(Error(typeof r.detail==='string'?r.detail:'上传失败'))};xhr.send(fd)})}
function importModal(kind){modal(kind==='orders'?'导入订单 CSV':'导入商品 CSV',`<form id="import-form" data-kind="${kind}"><div class="notice info">请先下载标准模板。金额单位为分；CSV 需为 UTF-8 编码。全部行校验通过后才会写入。</div>${kind==='orders'?selectField('导入到店铺','store_id',[['','请选择店铺'],...state.stores.map(s=>[s.id,s.name])]):'<p class="inline-help">相同 product_key 的多行组成一个商品的多个 SKU；重复导入相同 key 更新本地资料。不会自动更新平台商品。</p>'}<a class="btn" href="/api/export/${kind==='orders'?'order':'product'}-template">${icon('download')} 下载 CSV 模板</a><div class="field mt"><label>选择 CSV</label><input type="file" name="file" accept=".csv" required></div>${formFooter('校验并导入')}</form>`)}
function desktop(storeId='',kind='commerce_login',jobId=''){if(!state.desktop_ready){toast('当前环境未提供内嵌扫码桌面；本机运行请在 Chrome 窗口完成登录，Docker 请使用完整镜像。');return}const commerce=kind==='commerce_login';const token=modal('浏览器扫码窗口',`<p class="inline-help">登录页会在下方桌面打开。完成扫码或短信验证后，浏览器会自动关闭；若平台页面没有自动跳转，${commerce?'可点「我已完成登录」':'请刷新登录状态'}。</p><div id="desktop-state" class="notice ${storeId?'info':''}">${storeId?'正在创建登录任务…':'请从店铺卡片的登录按钮发起，登录状态按店铺分别保存。'}</div><div class="form-footer">${btn('关闭窗口','close')}${storeId&&commerce?btn('我已完成登录','commerce-login-confirm',true,`data-id="${esc(storeId)}"`):''}</div><iframe class="desktop-frame" src="/desktop/vnc.html?autoconnect=true&resize=scale&path=desktop/websockify" title="本地扫码桌面" allow="clipboard-read; clipboard-write"></iframe>`,true);if(storeId){desktopStore=storeId;watchLogin(storeId,token,kind,jobId)}}
function watchLogin(storeId,token,kind='commerce_login',jobId=''){
  clearTimeout(desktopTimer);
  const alive=()=>token===modalGeneration&&desktopStore===storeId&&$('#modal').open;
  const finish=async message=>{
    await refresh().catch(()=>{});
    if(alive())closeModal();
    if(page==='stores')await showPage(true).catch(()=>{});
    if(message)toast(message);
  };
  const tick=async()=>{
    if(!alive())return;
    try{
      const data=await api('/jobs?offset=0');
      if(!alive())return;
      const job=jobId?data.rows.find(j=>j.id===jobId):data.rows.find(j=>j.store_id===storeId&&j.kind===kind);
      const box=$('#desktop-state');
      if(job&&box){
        if(['queued','running'].includes(job.status)){
          box.className='notice info';
          box.textContent=job.status==='queued'?'登录任务已排队，正在启动浏览器…':'浏览器已打开，请完成扫码或短信验证。成功后窗口会自动关闭。';
        }else if(job.status==='succeeded'){
          await finish('登录成功，浏览器窗口已自动关闭');return;
        }else{
          await finish(`登录未完成：${job.result?.message||'请重新发起登录'}`);return;
        }
      }
    }catch{}
    if(alive())desktopTimer=setTimeout(tick,3000);
  };
  desktopTimer=setTimeout(tick,1200);
}
async function action(el){const a=el.dataset.action,id=el.dataset.id;if(a==='product-view'){productView=el.dataset.view==='cards'?'cards':'table';products();return}if(a==='kuaishou-preview'){kuaishouPreviewModal(id,el.dataset.storeId);return}if(a==='commerce-preview-status'){await commercePreview(id);return}if(a==='commerce-preview-desktop'){commercePreviewDesktop(id);return}if(a==='commerce-preview-close'){await api(`/jobs/${id}/preview/close`,{method:'POST',body:{}});toast('已请求结束此预览');await commercePreview(id);return}if(a==='commerce-readiness'){await commerceReadiness(id);return}if(a==='job-repreflight'){const job=cachedJobs.find(j=>j.id===id),pid=job?.entity_id||job?.payload.product?.id;if(!state.products.some(p=>p.id===pid)){toast('原商品已不存在，请重新选择商品',true);return}selected=new Set([pid]);batchModal(job.kind);const target=$$('#batch-form [name="store_ids"]').find(input=>input.value===job.store_id);if(target)target.checked=true;return}if(a==='refresh-stores'){await showPage(true);toast('已刷新登录状态');return}if(a==='commerce-login-confirm'){el.disabled=true;try{const r=await api(`/stores/${id}/commerce/login/confirm`,{method:'POST',body:{}});toast(r.message);const box=$('#desktop-state');if(box){box.className='notice info';box.textContent='正在核对登录页面，浏览器即将自动关闭…'}}catch(e){toast(e.message,true);el.disabled=false}return}if(a==='commerce-login'||a==='commerce-check'||a==='commerce-logout'){el.disabled=true;try{const r=await api(`/stores/${id}/commerce/${a.slice(9)}`,{method:'POST',body:{}});toast('电商后台任务已加入队列');if(a==='commerce-login')desktop(id,'commerce_login',r?.jobs?.[0]?.id);else location.hash='tasks'}finally{el.disabled=false}return}if(a==='fetch-skus'){const pid=editId;const r=await api(`/products/${pid}/listings/${id}/fetch-skus`,{method:'POST',body:{}});await refresh();mappings(pid);toast(`已匹配 ${Object.keys(r.sku_map).length} 个 SKU`);return}if(a==='publish-one'){selected=new Set([id]);if(window.PublishWorkbench)await PublishWorkbench.launch(workbenchContext(),[id]);else batchModal();return}if(a==='allocate'){allocationModal(id);return}if(a==='adjust-stock'){adjustmentModal(id);return}if(a==='inventory-refresh'){await refresh();await inventoryPage();return}if(a==='inventory-reconcile'){await api('/inventory/reconcile',{method:'POST',body:{}});await refresh();await inventoryPage();toast('已按当前映射重新核算，重复订单不重复扣减');return}if(a==='inventory-sync'){selected=new Set([id]);batchModal('inventory_sync');return}if(a==='remote-video-check'){const r=await api(`/jobs/${id}/remote-check`,{method:'POST',body:{}});toast(r.message);await tasks();return}if(a==='close'){closeModal();return}if(a==='refresh-page'){await showPage(true);return}if(a==='new-product')productModal();if(a==='edit-product')productModal(id);if(a==='add-sku')$('#sku-rows').insertAdjacentHTML('beforeend',skuRow());if(a==='remove-sku'){if($$('#sku-rows .sku-row').length>1)el.parentElement.remove();else toast('至少保留一个规格',true)}if(a==='mappings')mappings(id);if(a==='new-store')storeModal(null,el.dataset.platform);if(a==='edit-store')storeModal(id);if(a==='product-batch'){if(window.PublishWorkbench)await PublishWorkbench.launch(workbenchContext(),[...selected]);else batchModal();return}if(a==='product-manage')batchModal('product_update');if(a==='sync-orders')batchModal('order_sync');if(a==='upload-media')uploadModal();if(a==='import-orders')importModal('orders');if(a==='import-products')importModal('products');if(a==='desktop')desktop();if(a==='account-login'||a==='account-check'){const r=await api(`/stores/${id}/account/${a==='account-login'?'login':'check'}`,{method:'POST',body:{}});toast('视频账号任务已加入队列');if(a==='account-login')desktop(id,'account_login',r?.jobs?.[0]?.id);else location.hash='tasks'}if(a==='commit-batch'){el.disabled=true;try{const r=await api('/jobs',{method:'POST',body:pendingBatch});closeModal();toast(`已处理 ${r.jobs.length} 项任务，重复点击已自动去重`);await refresh();await navigateTo('tasks')}finally{el.disabled=false}}if(a==='search-orders'){orderOffset=0;await orders()}if(a==='orders-prev'){orderOffset=Math.max(0,orderOffset-50);await orders()}if(a==='orders-next'){orderOffset+=50;await orders()}if(a==='jobs-prev'){jobOffset=Math.max(0,jobOffset-100);await tasks()}if(a==='jobs-next'){jobOffset+=100;await tasks()}if(a==='refresh-tasks')await tasks();if(a==='filter-jobs'){jobFilter=el.dataset.value;await tasks()}if(a==='order-note'){const o=cachedOrders.find(x=>x.id===id);editId=id;modal('订单本地备注',`<form id="note-form"><p class="inline-help">订单 ${esc(o.external_id)} · 备注只保存在本地，不同步到平台。</p>${textField('备注','note',o.note)}${formFooter()}</form>`)}if(a==='delete-product'){editId=id;modal('删除本地商品资料',`<p class="inline-help">将删除「${esc(state.products.find(x=>x.id===id).title)}」及其店铺关联。平台上的商品保持原状。</p><div class="form-footer">${btn('取消','close')}${btn('确认删除本地资料','confirm-delete',true)}</div>`)}if(a==='confirm-delete'){await api(`/products/${editId}`,{method:'DELETE'});closeModal();await showPage(true);toast('本地商品已删除')}if(a==='job-cancel'){await api(`/jobs/${id}/action`,{method:'POST',body:{action:'cancel'}});await tasks();toast('已取消等待中的任务')}if(a==='job-retry'){const j=cachedJobs.find(x=>x.id===id);editId=id;modal('重试任务',`<form id="retry-form"><div class="notice">${esc(j.result.message)}。重试将沿用原任务的商品、文案和挂载参数。</div>${j.status==='uncertain'?'<label class="check-label"><input type="checkbox" name="checked_remote" required>我已核对平台后台，确认没有发布成功，可以重试。</label>':'<p class="inline-help">若商品模板或商品内容已修改，请取消旧任务，重新预检创建。</p>'}${formFooter('发起重试')}</form>`)}if(a==='job-confirm'){editId=id;modal('确认平台实际结果',`<form id="confirm-job-form"><p class="inline-help">确认商品 / 视频已在正确店铺提交，且商品关联正确。创建商品若未自动返回 ID，请同时去商品中心手动关联。</p>${selectField('核对结论','outcome',[['confirm','确认已提交成功'],['mark_failed','确认未发布成功']])}${textField('平台商品 ID / 作品链接 / 核对说明','evidence')}<label class="check-label"><input name="checked_remote" type="checkbox" required>我已在对应店铺后台核对实际结果。</label>${formFooter('保存核对结论')}</form>`)}if(a==='job-detail'){const j=cachedJobs.find(x=>x.id===id);if(j.kind==='commerce_prepare_product'){await commercePreview(id);return}const log=await api(`/jobs/${id}/log`);modal('任务详情',`<div class="actions">${badge(j.status,jobStatusLabel(j))}<strong>${kindName(j.kind)} · ${esc(j.store_name)}</strong></div><p class="inline-help">任务 ID：${esc(j.id)}</p><pre>${esc(j.result.message)}</pre>${j.kind==='video_publish'&&j.status==='running'&&j.platform==='douyin'?`<form id="sms-form" data-id="${j.store_id}">${field('平台要求的短信验证码','code')}<button class="btn" type="submit">提交验证码</button></form>`:''}<details><summary>任务参数快照</summary><pre>${esc(JSON.stringify(j.payload,null,2))}</pre></details><h3 class="section-title mt">执行日志</h3><pre>${esc(log.text)}</pre>`,true)}}
$('#modal').addEventListener('cancel',invalidateModalWork);
$('#modal').addEventListener('close',()=>{if(!$('#modal').open)invalidateModalWork()});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el).catch(err=>toast(err.message,true))}});
document.addEventListener('input',e=>{if(e.target.id==='product-search'){productQuery=e.target.value;const list=visibleProducts();$('#product-table').innerHTML=list.length?productCollection(list):empty('products','没有找到匹配商品')}});
document.addEventListener('change',async e=>{if(e.target.id==='product-category'){productCategory=e.target.value;products();return}if(e.target.name==='preview_store_id'){kuaishouPreviewModal($('#commerce-preview-form').dataset.productId,e.target.value);return}if(e.target.name==='upload_images'&&e.target.closest('#commerce-preview-form')){$('#commerce-preview-form [type=submit]').textContent=e.target.checked?'上传图片并准备表单':'准备表单（不上传图片）';return}if(e.target.matches('.product-select')){e.target.checked?selected.add(e.target.value):selected.delete(e.target.value);$('#selected-count').textContent=`已选 ${selected.size} 件`}if(e.target.id==='select-all'){visibleProducts().forEach(p=>e.target.checked?selected.add(p.id):selected.delete(p.id));products()}if(e.target.name==='media_id'&&$('#video-preview'))$('#video-preview').innerHTML=e.target.value?`<video src="/api/media/${esc(e.target.value)}" controls style="max-height:220px;width:100%;margin-bottom:18px;border-radius:8px"></video>`:'';if(e.target.id==='product-cover-upload'&&e.target.files[0]){try{const chosen=$$('[name="image_ids"]:checked').map(i=>i.value),details=$$('[name="detail_image_ids"]:checked').map(i=>i.value);for(const file of e.target.files){toast('正在上传 '+file.name);const r=await uploadFile(file);chosen.push(r.id)}await refresh();$('#product-images').innerHTML=imageChoices({image_ids:chosen,detail_image_ids:details});toast('商品图片已保存到本地仓库')}catch(err){toast(err.message,true)}}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id)return;e.preventDefault();const fd=new FormData(form),v=Object.fromEntries(fd),submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{if(form.id==='commerce-preview-form'){const business={category_path:v.preview_category_path.split('\n').map(x=>x.trim()).filter(Boolean),brand:v.preview_brand,material:v.preview_material,closure:v.preview_closure,freight_template:v.preview_freight_template};const r=await api(`/stores/${v.preview_store_id}/commerce/prepare-product`,{method:'POST',body:{product_id:form.dataset.productId,upload_images:fd.has('upload_images'),business}});const jobId=r.jobs?.[0]?.id;if(!jobId)throw Error('预览任务未返回编号，请查看任务队列');toast('快手填表预览已入队，程序不会提交审核');await refresh();await commercePreview(jobId);return}if(form.id==='auth-form'){const r=await api('/auth/'+form.dataset.mode,{method:'POST',body:{username:v.username,password:v.password}});csrf=r.csrf;await boot();return}if(form.id==='product-form'){const skus=$$('#sku-rows .sku-row').map(row=>{const get=k=>row.querySelector(`[data-key="${k}"]`).value;return {code:get('code'),name:get('name'),price_cents:Math.round(Number(get('price'))*100),stock:Number(get('stock'))}});const body={title:v.title,description:v.description,category:v.category,cover_id:v.cover_id,image_ids:fd.getAll('image_ids'),detail_image_ids:fd.getAll('detail_image_ids'),skus,images:v.images.split('\n').map(x=>x.trim()).filter(Boolean),extra:JSON.parse(v.extra||'{}')};if(editId)body.version=state.products.find(p=>p.id===editId).version;await api('/products'+(editId?'/'+editId:''),{method:editId?'PUT':'POST',body});toast('商品已保存到本地')}if(form.id==='store-form'){const existing=state.stores.find(s=>s.id===editId);const body={name:v.name,platform:existing?.platform||v.platform,commerce_enabled:fd.has('commerce_enabled'),video_enabled:fd.has('video_enabled'),credentials:{video_app_id:v.video_app_id,video_access_token:v.video_access_token},templates:readStoreTemplates(v,fd)};await api('/stores'+(editId?'/'+editId:''),{method:editId?'PUT':'POST',body});toast('店铺设置已保存')}if(form.id==='mapping-form'){for(const s of state.stores){const sku_map={};for(const sku of state.products.find(p=>p.id===editId).skus){const remote=v[s.id+'_sku_'+sku.code];if(remote)sku_map[sku.code]=remote}await api(`/products/${editId}/listings/${s.id}`,{method:'PUT',body:{external_id:v[s.id+'_id'],product_link:v[s.id+'_link'],publish_config:JSON.parse(v[s.id+'_config']||'{}'),sku_map,owned_product:fd.has(s.id+'_owned')}})}toast('店铺商品配置已保存')}if(form.id==='video-form'){await preflight({kind:'video_publish',store_ids:fd.getAll('store_ids'),media_id:v.media_id,product_id:v.product_id,title:v.title,description:v.description,tags:v.tags,attach_product:fd.has('attach_product'),cover_id:v.cover_id,scheduled:v.scheduled?Math.floor(new Date(v.scheduled).getTime()/1000):null});return}if(form.id==='batch-form'){const body={kind:v.kind,store_ids:fd.getAll('store_ids'),product_ids:(v.kind.startsWith('product')||v.kind==='inventory_sync')?[...selected]:[],sales_paused:fd.has('sales_paused')};if(v.scheduled)body.scheduled=Math.floor(new Date(v.scheduled).getTime()/1000);if(v.kind==='order_sync'){body.since=Math.floor(new Date(v.since).getTime()/1000);body.until=Math.floor(new Date(v.until).getTime()/1000)}await preflight(body);return}if(form.id==='upload-form'){await uploadFile(fd.get('file'),$('#upload-progress'));toast('素材上传完成')}if(form.id==='import-form'){if(form.dataset.kind==='orders'&&!v.store_id)throw Error('请选择店铺');const body=new FormData();body.append('file',fd.get('file'));const r=await api(form.dataset.kind==='orders'?`/import/orders/${v.store_id}`:'/import/products',{method:'POST',body});toast(`成功导入 / 更新 ${r.count} 条${r.skipped?`；保留 ${r.skipped} 条平台同步记录`:''}`)}if(form.id==='allocation-form'){const p=state.products.find(p=>p.id===editId),quantities={};for(const [i,sku] of p.skus.entries()){quantities[sku.code]={};for(const st of state.stores)quantities[sku.code][st.id]=Number(v[i+'_'+st.id])}await api(`/products/${editId}/allocations`,{method:'PUT',body:{version:Number(v.version),quantities}});toast('店铺可售额度已保存；点击校准将额度提交平台')}if(form.id==='adjustment-form'){await api(`/products/${editId}/inventory-adjustment`,{method:'POST',body:{version:Number(v.version),sku_code:v.sku_code,delta:Number(v.delta),reason:v.reason}});toast('库存调整已记账')}if(form.id==='note-form'){await api(`/orders/${editId}/note`,{method:'PUT',body:{note:v.note}});toast('本地备注已保存')}if(form.id==='confirm-job-form'){await api(`/jobs/${editId}/action`,{method:'POST',body:{action:v.outcome,evidence:v.evidence,checked_remote:fd.has('checked_remote')}});toast('核对结论已保存')}if(form.id==='retry-form'){await api(`/jobs/${editId}/action`,{method:'POST',body:{action:'retry',checked_remote:fd.has('checked_remote')}});toast('已加入重试队列')}if(form.id==='sms-form'){await api(`/stores/${form.dataset.id}/verify`,{method:'POST',body:{code:v.code}});toast('验证码已提交');return}closeModal();await showPage(true)}catch(err){const target=form.querySelector('.form-error')||$('#video-error');if(target)target.textContent=err.message;else toast(err.message,true)}finally{if(submit)submit.disabled=false}});
$('#logout').addEventListener('click',async()=>{await api('/auth/logout',{method:'POST',body:{}});++routeGeneration;stopPagePolling();await boot()});
window.addEventListener('hashchange',()=>{orderOffset=0;jobOffset=0;showPage(true)});
async function boot(){try{const auth=await api('/auth/status');csrf=auth.csrf;$('#shell').hidden=!auth.authenticated;$('#auth').hidden=auth.authenticated;if(auth.authenticated){await refresh();await showPage();$('#clock').textContent=new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'});return}++routeGeneration;stopPagePolling();const setup=!auth.initialized;$('#auth').innerHTML=`<div class="auth-art"><div class="brand"><img src="/assets/logo.svg" alt="">ShopDock</div><h1>把每一份生意，<br>打理得从容一点。</h1><p>一处准备商品，一处查看订单。<br>让好内容去往更多渠道，让重复的工作少一点。</p><div class="auth-steps"><span>商品管理</span><span>订单汇总</span><span>视频分发</span></div></div><div class="auth-panel"><div class="auth-box"><div class="eyebrow">YOUR LOCAL COMMERCE WORKSPACE</div><h2>${setup?'欢迎来到你的工作台。':'欢迎回来。'}</h2><p>${setup?'创建管理员账号，开始管理你的多平台店铺。账号与凭据保存在本机。':'登录 ShopDock，继续打理你的店铺与内容。'}</p><form id="auth-form" data-mode="${setup?'setup':'login'}">${field('管理员账号','username','admin')}${field('密码','password','','password',setup?'至少 12 位，自行设置，没有默认密码。':'')}<div class="form-error"></div><button class="btn primary" type="submit">${setup?'创建本地工作台':'进入工作台'} ${icon('arrow')}</button></form><p class="auth-note">本地部署 · 无软件订阅费 · 数据由你掌握</p></div></div>`}catch(e){$('#auth').hidden=false;$('#auth').innerHTML=`<div class="auth-panel"><div class="error-state">无法连接服务：${esc(e.message)}<br>请检查 Docker 容器是否启动。</div></div>`}}
function imageChoices(p){if(window.MediaLibrary)return MediaLibrary.imageChoices(p,state.media);const imgs=state.media.filter(m=>m.kind==='image');return `<div class="field"><label>商品主图（按素材列表顺序，抖店标准映射需 3–5 张）</label>${imgs.map(m=>`<label class="check-label"><input type="checkbox" name="image_ids" value="${m.id}" ${(p?.image_ids||[]).includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')||'<p class="inline-help">先上传图片。</p>'}</div><details><summary>选择本地详情图</summary>${imgs.map(m=>`<label class="check-label"><input type="checkbox" name="detail_image_ids" value="${m.id}" ${(p?.detail_image_ids||[]).includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</details>`}
function readStoreTemplates(v,fd){const t=JSON.parse(v.templates||'{}');t.auto_order_sync=fd.has('auto_order_sync');if(v.category_id||v.freight_id){t.publish_defaults={...(t.publish_defaults||{}),category_id:v.category_id,freight_id:v.freight_id}}return t}
function sampleBrowserConfig(){return {commerce_browser:{
  logged_in:{text:'商品管理'},login_required:{text:'扫码登录'},
  identity:{target:{css:'.__REQUIRED__店名控件'},value:'__REQUIRED__实际后台店名'},
  workflows:{product_create:{url:'/__REQUIRED__实际商品编辑路由',steps:[
    {op:'fill',target:{label:'商品名称'},value:'{{product.title}}'},
    {op:'upload',target:{css:'input.__REQUIRED__商品图片[type=file]'},value:'{{product.image_ids}}'},
    {op:'each_sku',steps:[
      {op:'fill',target:{css:'.__REQUIRED__sku-code',nth:'{{index}}'},value:'{{sku.code}}'},
      {op:'fill',target:{css:'.__REQUIRED__sku-price',nth:'{{index}}'},value:'{{sku.price}}'},
      {op:'fill',field:'stock',target:{css:'.__REQUIRED__sku-stock',nth:'{{index}}'},value:'{{sku.stock}}'}
    ]},
    {op:'click',target:{role:'button',name:'__REQUIRED__实际保存按钮'},commit:true}
  ],result:{
    success:{text:'__REQUIRED__实际成功提示'},external_id:{css:'.__REQUIRED__product-id',regex:'([0-9]+)'},
    rows:{css:'.__REQUIRED__保存后SKU表格行'},
    fields:{code:{css:'.__REQUIRED__sku-code',input:true},sku_id:{css:'.__REQUIRED__sku-id'},stock:{css:'.__REQUIRED__sku-stock',input:true}}
  }}}
}}}
function mappings(id){editId=id;const p=state.products.find(x=>x.id===id);modal('多店铺货配置与 SKU 关联',`<p class="inline-help">${esc(p.title)} · 商品标题、价格、图片、规格从本地仓库自动映射。请先在店铺设置中验证后台网页规则、当前店铺身份与提交回执，再配置各店类目 / 运费 / 品牌资质；发布后核对平台商品与 SKU ID。</p><form id="mapping-form">${state.stores.map(s=>{const l=state.listings.find(l=>l.product_id===id&&l.store_id===s.id)||{},conf=l.publish_config||{};return `<section class="card mt"><div class="card-head"><div class="store-title">${logo(s.platform)}<strong>${esc(s.name)}</strong></div></div><div class="card-body">${textField('商品在本店的发布配置 JSON',s.id+'_config',JSON.stringify(conf,null,2),'留空对象使用店铺默认值。示例：{"category_id":"123","freight_id":"456","native":{}}','json-input')}<div class="form-grid">${field('平台商品 ID（新建前留空）',s.id+'_id',l.external_id||'')}${field('HTTPS 商品分享链接',s.id+'_link',l.product_link||'','url')}</div>${s.platform==='kuaishou'?`<label class="check-label"><input type="checkbox" name="${s.id}_owned" ${l.owned_product?'checked':''}>已核对：这是该快手视频账号的自建商品，可挂小黄车</label>`:''}<details ${l.external_id?'open':''}><summary>各规格的平台 SKU ID（库存与订单扣库必填）</summary>${l.external_id?btn('按外部编码获取 SKU','fetch-skus',false,`data-id="${s.id}"`):''}${p.skus.map(sku=>field(esc(sku.name)+' · '+esc(sku.code),s.id+'_sku_'+sku.code,l.sku_map?.[sku.code]||'')).join('')}</details></div></section>`}).join('')||'<div class="notice">请先添加店铺。</div>'}${formFooter('保存多店配置')}</form>`,true)}
function capabilityTable(){return `<div class="table-wrap"><table><thead><tr><th>平台</th><th>商品管理</th><th>订单与库存</th><th>视频发布</th></tr></thead><tbody>${Object.entries(state.platforms).map(([id,p])=>`<tr><td>${esc(p.name)}</td><td>${id==='kuaishou'?'统一发布内置创建 / 更新；编辑 / 上下架按页面规则':'统一发布通用内置创建；编辑 / 上下架按页面规则'}<br><small>${id==='kuaishou'?'创建仍需实际页面、评分和回执检查':'更新与审核回查需配置页面地址；创建需实际页面与回执检查'}</small></td><td>网页订单同步 / SKU 关联 / 库存校准<br><small>也支持 CSV 汇总</small></td><td>${id==='kuaishou'?'独立视频登录；官方挂商品需 Video 授权':p.link?'独立视频登录与商品挂载':'独立视频登录'}</td></tr>`).join('')}</tbody></table></div>`}
let inventoryData={rows:[],alerts:[],ledger:[]};
async function inventoryPage(generation=routeGeneration){if(!routeCurrent('inventory',generation))return;const data=await api('/inventory');if(!routeCurrent('inventory',generation))return;inventoryData=data;$('#main').innerHTML=heading('一份实物库存，分配给所有店。','每店可售额度合计不超过仓库余额。网页订单按 SKU 扣一次；退货验收后手动入库。',btn('重新核算订单','inventory-reconcile')+btn('刷新','inventory-refresh'),'UNIFIED INVENTORY')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>商品 / SKU</th><th>仓库余额</th><th>店铺额度占用</th><th>尚未分配</th><th>各店可售额度</th><th>操作</th></tr></thead><tbody>${inventoryData.rows.map(r=>`<tr><td><strong>${esc(r.title)}</strong><div class="subtle">${esc(r.code)} · ${esc(r.name)}</div></td><td>${r.stock}</td><td>${r.held}</td><td>${r.unallocated}</td><td>${r.allocations.map(a=>`${esc(storeName(a.store_id))}：${a.quantity} / 远端记录 ${a.remote_quantity}${a.uncertain?' · 需核对':''}`).join('<br>')||'尚未分配'}</td><td><div class="actions">${btn('分配','allocate',false,`data-id="${r.product_id}"`)}${btn('出入库','adjust-stock',false,`data-id="${r.product_id}"`)}${btn('校准到店铺','inventory-sync',false,`data-id="${r.product_id}"`)}</div></td></tr>`).join('')}</tbody></table></div></section><div class="notice info">例如仓库 10 件，可分配抖店 4、快手 3、微信 3。减少某店额度后，必须先成功校准远端，才释放该店占用。全量校准前须暂停销售并核对锁定库存；这是额度分仓，订单轮询期间不会把一份库存同时补回三家店。</div><section class="card"><div class="card-head"><h2>需要核对的库存订单 · ${inventoryData.alerts.length}</h2></div><div class="card-body">${inventoryData.alerts.map(a=>`<p>${esc(storeName(a.store_id))} · ${esc(a.order_id)}：${esc(a.message)}</p>`).join('')||'暂无异常'}</div></section><section class="card"><div class="card-head"><h2>最近库存流水</h2></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>SKU</th><th>变动</th><th>原因 / 订单</th></tr></thead><tbody>${inventoryData.ledger.map(l=>`<tr><td>${date(l.created)}</td><td>${esc(l.sku_code)}</td><td>${l.delta>0?'+':''}${l.delta}</td><td>${esc(l.reason)} ${esc(l.order_id)}</td></tr>`).join('')}</tbody></table></div></section>`}
function allocationModal(id){editId=id;const p=state.products.find(p=>p.id===id),rows=inventoryData.rows.filter(r=>r.product_id===id);modal('分配店铺可售额度',`<form id="allocation-form"><input type="hidden" name="version" value="${p.version}"><p class="inline-help">${esc(p.title)} · 不填超出库存的额度。远端未确认减少的数量仍占用仓库额度。</p>${p.skus.map((sku,i)=>`<h3>${esc(sku.name)} · 仓库余额 ${sku.stock}</h3><div class="form-grid">${state.stores.map(st=>field(esc(st.name),i+'_'+st.id,rows.find(r=>r.code===sku.code)?.allocations.find(a=>a.store_id===st.id)?.quantity||0,'number')).join('')}</div>`).join('')}${formFooter('保存分配')}</form>`,true)}
function adjustmentModal(id){editId=id;const p=state.products.find(p=>p.id===id);modal('实物出入库',`<form id="adjustment-form"><input type="hidden" name="version" value="${p.version}">${selectField('规格','sku_code',p.skus.map(s=>[s.code,s.name]))}${field('数量变化（入库为正，出库为负）','delta',1,'number')}${field('原因（采购 / 退货验收 / 盘点等）','reason')}${formFooter('记入库存流水')}</form>`)}

window.MediaLibrary?.configure(workbenchContext());
boot();
